#include <iostream>
#include <vector>
using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    cin >> n;

    vector<vector<int>> a(n, vector<int>(n));
    int r = 0, c = 0;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            cin >> a[i][j];
            if (a[i][j] == 0) { r = i; c = j; }
        }
    }

    // Soma mágica: soma de uma linha completa (existe, pois N >= 3 e há só um zero)
    int S = 0;
    for (int i = 0; i < n; i++) {
        if (i == r) continue;
        S = 0;
        for (int j = 0; j < n; j++) S += a[i][j];
        break;
    }

    // Soma da linha que contém o número ilegível (o zero conta como 0)
    int rowSum = 0;
    for (int j = 0; j < n; j++) rowSum += a[r][j];

    cout << (S - rowSum) << "\n";
    cout << (r + 1) << "\n";
    cout << (c + 1) << "\n";

    return 0;
}
